// LoggingAspect
@Around("execution(* in.strikes.aopDemo.service.StudentService.dummyMethod(..))")
public Object logAroundMethod(ProceedingJoinPoint joinPoint) throws Throwable {
    Object return1 = joinPoint.proceed();
    System.out.println("Intercepted, calling again");
    Object return2 = joinPoint.proceed();
    return return2;
}

// StudentService
public String dummyMethod(String s) {
    System.out.println("dummyMethod called: " + s);
    return s;
}

// LoggingAspect
@Around("execution(* in.strikes.aopDemo.service.StudentService.dummyMethod(..))")
public Object logAroundMethod(ProceedingJoinPoint joinPoint) throws Throwable {
    Object[] arr = joinPoint.getArgs();
    String modified = ((String) arr[0]).toUpperCase();
    String result = (String) joinPoint.proceed(new Object[]{ modified });
    return result + " : String Intercepted";
}

@Around("execution(* in.strikes.aopDemo.service.StudentService.createStudent(..))")
public Object around(ProceedingJoinPoint pjp) throws Throwable {
    System.out.println("Around-before");
    Object r = pjp.proceed();
    System.out.println("Around-after");
    return r;
}

